    /// <summary>
    /// Customer Tobacco Licence validations while creating Sales line
    /// </summary>
    /// <param name="sender">Get Table buffer</param>
    /// <param name="e"> Get Sales Table args</param>
    [
        DataEventHandler(tableStr(SalesLine), DataEventType::Inserting),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage") 
    ]
    public static void SalesLine_onInserting(Common sender, DataEventArgs e)
    {
        SalesLine salesLine = sender as SalesLine;
        SalesTable salesTable = salesLine.salesTable();

        if(salesTable.METTobaccoLicenceValidationRequired == NoYes::Yes
            && salesTable.METValidTobaccoLicence == NoYes::Yes
                && METCustParameters::Find().TobaccoFilterCodes == WHSInventTable::find(salesLine.ItemId, false).FilterCode[1]
                    && salesTable.METCustTobaccoReasonCode)
        {
            salesLine.METCustTobaccoReasonCode = salesTable.METCustTobaccoReasonCode;
            salesLine.Blocked = NoYes::Yes;
        }
    }
